class Container:
    def __init__(self):
        self._providers = {}
        self._singletons = {}

    def register(self, name, provider, singleton=False):
        self._providers[name] = (provider, singleton)

    def resolve(self, name, **kwargs):
        if name not in self._providers:
            raise KeyError(f'not registered: {name}')
        provider, singleton = self._providers[name]
        if singleton:
            if name not in self._singletons:
                self._singletons[name] = provider(**kwargs) if callable(provider) else provider
            return self._singletons[name]
        return provider(**kwargs) if callable(provider) else provider

