class IdGenerator:
    def __init__(self):
        self._counts = {}

    def next_id(self, base):
        cleaned = ''.join(ch if ch.isalnum() else '-' for ch in base.lower()).strip('-')
        cleaned = '-'.join(filter(None, cleaned.split('-')))
        self._counts[cleaned] = self._counts.get(cleaned, 0) + 1
        return cleaned if self._counts[cleaned] == 1 else f'{cleaned}-{self._counts[cleaned]}'

