import os

def load_config(prefix='APP_', defaults=None):
    config = {}
    for key, default in (defaults or {}).items():
        raw = os.environ.get(prefix + key.upper())
        if raw is None:
            config[key] = default
        elif isinstance(default, bool):
            config[key] = raw.strip().lower() in ('1', 'true', 'yes', 'on')
        elif isinstance(default, int):
            config[key] = int(raw)
        elif isinstance(default, float):
            config[key] = float(raw)
        else:
            config[key] = raw
    return config

