def build_histogram(counts, width=20):
    if not counts:
        return ''
    top = max(counts.values()) or 1
    lines = []
    for label, value in counts.items():
        bar = '#' * max(1, round(value / top * width)) if value else ''
        lines.append(f'{label:>8} | {bar} {value}')
    return '\n'.join(lines)

