def ascii_table(rows):
    if not rows:
        return ''
    headers = list(rows[0])
    data = [[str(row.get(h, '')) for h in headers] for row in rows]
    widths = [max(len(h), *(len(r[i]) for r in data)) for i, h in enumerate(headers)]
    line = '+'.join('-' * (w + 2) for w in widths)
    def fmt(cells):
        return '|'.join(' ' + c.ljust(w) + ' ' for c, w in zip(cells, widths))
    out = [fmt(headers), line] + [fmt(r) for r in data]
    return '\n'.join(out)

